export function memoryThumbStore() {
    const m = new Map();
    return { async get(k) { return m.get(k); }, async set(k, v) { m.set(k, v); }, async delete(k) { m.delete(k); }, async clear() { const n = m.size; m.clear(); return n; } };
}
/** IndexedDB 实现：一个 DB 一个 object store（keyPath 无，out-of-line key）。打开失败自动重试一次（WeebPaint openDB 的自愈）。 */
export function idbThumbStore(opts) {
    const storeName = opts.storeName ?? "thumbs", version = opts.version ?? 1;
    let _db = null;
    const open = () => new Promise((resolve, reject) => {
        const req = indexedDB.open(opts.dbName, version);
        req.onupgradeneeded = () => { const db = req.result; if (!db.objectStoreNames.contains(storeName))
            db.createObjectStore(storeName); };
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error);
        req.onblocked = () => reject(new Error("idb open blocked"));
    });
    const db = () => { if (_db)
        return _db; _db = open().catch(async (e1) => { try {
        return await open();
    }
    catch {
        _db = null;
        throw e1;
    } }); return _db; };
    const tx = async (mode, run) => {
        const d = await db();
        return new Promise((resolve, reject) => {
            const t = d.transaction(storeName, mode);
            const s = t.objectStore(storeName);
            const r = run(s);
            let out;
            if (r) {
                r.onsuccess = () => { out = r.result; };
                r.onerror = () => reject(r.error);
            }
            t.oncomplete = () => resolve(out);
            t.onerror = () => reject(t.error);
        });
    };
    return {
        get: (k) => tx("readonly", (s) => s.get(k)),
        set: (k, v) => tx("readwrite", (s) => { s.put(v, k); }),
        delete: (k) => tx("readwrite", (s) => { s.delete(k); }),
        clear: () => tx("readwrite", (s) => { const c = s.count(); c.onsuccess = () => { s.clear(); }; return c; }),
    };
}
