/** 0.5.0：按种类的默认存法。**音频 / 视频默认「只放内存」（当次有效）**，图片 / 文字默认随文档保存。
 *  user 2026-10-21「音视频应该是当此有效，后来应该拍了」；2026-10-09「能不能加 RAM only，就是不落盘，每次重新上传，这个非常有用！！！」。宿主可按种类覆盖（RefImportOptions.defaultRam）。 */
export const DEFAULT_RAM = { image: false, text: false, audio: true, video: true };
/** 看 mime（再看扩展名）是哪种卡；认不出 = null。 */
export function sniffKind(f) {
    const t = (f.type || "").toLowerCase(), n = (f.name || "").toLowerCase();
    if (t.startsWith("image/"))
        return "image";
    if (t.startsWith("audio/"))
        return "audio";
    if (t.startsWith("video/"))
        return "video";
    if (t.startsWith("text/") || /\.(txt|md)$/.test(n))
        return "text";
    if (/\.(mp3|m4a|wav|flac|ogg|opus|aac|weba)$/.test(n))
        return "audio";
    if (/\.(png|jpe?g|webp|gif)$/.test(n))
        return "image";
    if (/\.(mp4|webm|mov)$/.test(n))
        return "video";
    return null;
}
/** 一个一个进牌组（顺序 = 给的顺序）；每张问不问、压不压按上面的规矩。不抛：每个文件的结果写在 added / skipped 里，调用方如实说。 */
export async function importIntoDeck(deck, files, o) {
    const out = { added: [], filled: [], skipped: [], notes: [] };
    for (const f of files) {
        const name = f.name ?? "", kind = sniffKind(f);
        if (!kind || !o.kinds.includes(kind)) {
            out.skipped.push({ name, why: "unsupported" });
            continue;
        }
        // 「只放内存」的空位：同种类、同名 = 补回原位（不问、不新加；位置 / 播放位置 / 循环都还在）
        const hole = deck.cards().find((c) => c.ram && !c.bytes && c.kind === kind && c.name === name);
        if (hole) {
            deck.fill(hole.id, f, f.type || undefined);
            deck.select(deck.indexOf(hole.id));
            out.filled.push(hole);
            continue;
        }
        try {
            // 默认存法按种类（0.5.0：音视频默认只放内存）；问了 = 用户的选择说了算（keep / compress 都是「存进文档」）
            const ramDefault = o.defaultRam?.[kind] ?? DEFAULT_RAM[kind];
            let blob = f, mime = f.type || "", ram = ramDefault;
            const canCompress = !!o.transcoder?.kinds.includes(kind), limit = o.askAbove?.[kind];
            if (o.ask && limit !== undefined && f.size > limit) {
                const estimate = canCompress && o.transcoder?.estimate ? await o.transcoder.estimate(kind, f).catch(() => null) : null;
                const choice = await o.ask({ name, kind, bytes: f.size, estimate, canCompress, suggestRam: ramDefault || (o.ramAbove !== undefined && f.size > o.ramAbove) });
                if (choice === "cancel") {
                    out.skipped.push({ name, why: "cancelled" });
                    continue;
                }
                ram = choice === "ram";
                if (choice === "compress" && canCompress) {
                    const r = await o.transcoder.encode(kind, f);
                    blob = r.blob;
                    mime = r.mime;
                    if (r.note)
                        out.notes.push(`${name}: ${r.note}`);
                }
            }
            if (kind === "text" && !mime)
                mime = /\.md$/i.test(name) ? "text/markdown" : "text/plain";
            const id = deck.add({ kind, bytes: blob, mime, name, ...(ram ? { ram: { bytes: blob.size } } : {}) });
            const c = deck.cards().find((x) => x.id === id);
            if (c)
                out.added.push(c);
        }
        catch (e) {
            out.skipped.push({ name, why: "failed", message: String(e?.message ?? e) });
        }
    }
    return out;
}
