import { note as diagNote } from "../guards/diag-log.js"; // 0.8.7：没配库名时记一次
const mintId = () => "g" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const oneDriveLabel = (username) => "OneDrive · " + (username || "账号");
// legacy 连续性（P3 Slice C 拍定）：认领 "defaultStore" 命名空间的那个条目，id 同时取 **"default"**
//   （= SOLE_GALLERY_ID）——锁名 `default:名`、回执条键 `resume:default` 与 P3 前逐字节相同，零迁移。
const LEGACY_ID = "default";
const LEGACY_DB = "defaultStore";
export function createGalleryRegistry(kv) {
    const findSame = async (entries, handle) => {
        for (const e of entries) {
            if (e.kind !== "folder" || !e.handle)
                continue;
            try {
                if (await e.handle.isSameEntry(handle))
                    return e;
            }
            catch { /* 句柄失活 → 视为不同 */ }
        }
        return null;
    };
    return {
        list: () => kv.list(),
        async mintFolder(handle) {
            const entries = await kv.list();
            const same = await findSame(entries, handle);
            if (same) {
                const fresh = { ...same, handle, label: handle.name || same.label }; // 复用 id + 句柄/标签刷新
                await kv.put(fresh);
                return fresh;
            }
            const id = mintId();
            const e = { id, kind: "folder", label: handle.name || "文件夹", dbId: `gallery-${id}`, handle, lastActive: null, createdAt: Date.now() };
            await kv.put(e);
            return e;
        },
        async mintOneDrive(homeAccountId, username) {
            const entries = await kv.list();
            const same = entries.find((e) => e.kind === "onedrive" && e.homeAccountId === homeAccountId);
            if (same) {
                const fresh = { ...same, label: oneDriveLabel(username) };
                await kv.put(fresh);
                return fresh;
            }
            const legacyFree = !entries.some((e) => e.dbId === LEGACY_DB);
            const id = legacyFree ? LEGACY_ID : mintId();
            const e = { id, kind: "onedrive", label: oneDriveLabel(username), dbId: legacyFree ? LEGACY_DB : `gallery-${id}`, homeAccountId, lastActive: null, createdAt: Date.now() };
            await kv.put(e);
            return e;
        },
        async touch(id) {
            const e = (await kv.list()).find((x) => x.id === id);
            if (e)
                await kv.put({ ...e, lastActive: Date.now() });
        },
        async clearLastActive() {
            for (const e of await kv.list())
                if (e.lastActive !== null)
                    await kv.put({ ...e, lastActive: null });
        },
        async relabel(id, label) {
            const e = (await kv.list()).find((x) => x.id === id);
            if (e && label && e.label !== label)
                await kv.put({ ...e, label });
        },
        forget: (id) => kv.delete(id),
        async lastActive() {
            let best = null;
            for (const e of await kv.list())
                if (e.lastActive !== null && (!best || e.lastActive > best.lastActive))
                    best = e;
            return best;
        },
        async seedLegacyOneDrive(p) {
            if (!p.homeAccountId)
                return;
            const entries = await kv.list();
            if (entries.some((e) => e.kind === "onedrive" && e.homeAccountId === p.homeAccountId))
                return; // 幂等：见过就不再播
            const legacyFree = !entries.some((e) => e.dbId === LEGACY_DB);
            const id = legacyFree ? LEGACY_ID : mintId();
            await kv.put({
                id, kind: "onedrive", label: oneDriveLabel(p.username), homeAccountId: p.homeAccountId,
                dbId: legacyFree ? LEGACY_DB : `gallery-${id}`, // 既有用户的数据物理在 defaultStore——条目认领它（id 同取 "default"），零迁移
                lastActive: Date.now(),
                createdAt: Date.now(),
            });
        },
    };
}
// ─── IDB 适配器（浏览器；node 测试用 Map 假件替代本段。形状抄 crash-store，刻意 WET）──────────
// 0.8.7（道 6 F-58 §8 第 2 件，user 2026-10-21「gallery-registry 库名改宿主传 可以」）：库名归宿主——这是宿主的设备记事本（ADR-0024），不该带 WeebPaint 的 GUID 写死在包里。
//   configureGalleryRegistry({ dbName }) 在第一次开库之前配；没配 = 退回老字面量（既有 WeebPaint 用户零迁移）+ diag 记一次；开过库再配 = 编程错误，响亮抛。
const LEGACY_DB_NAME = "weebpaint-bd6cece69075d759.gallery-registry";
const STORE = "entries"; // key = 铸的 id
let _dbName = null;
let _opened = false;
let _warnedLegacy = false;
export function configureGalleryRegistry(opts) {
    if (!opts?.dbName)
        throw new Error("configureGalleryRegistry: dbName required");
    if (_opened)
        throw new Error(`configureGalleryRegistry: too late — the registry database was already opened as "${_dbName ?? LEGACY_DB_NAME}" (configure before the first gallery call)`);
    _dbName = opts.dbName;
}
/** 实际用的库名（没配 = 老字面量）；测试 / 诊断用。 */
export function galleryRegistryDbName() { return _dbName ?? LEGACY_DB_NAME; }
let _dbPromise = null;
function _openDB() {
    if (_dbPromise)
        return _dbPromise;
    if (!_dbName && !_warnedLegacy) {
        _warnedLegacy = true;
        diagNote("gallery", `gallery-registry: host did not call configureGalleryRegistry({ dbName }); using legacy database name "${LEGACY_DB_NAME}"`);
    }
    _opened = true;
    _dbPromise = new Promise((resolve, reject) => {
        const req = indexedDB.open(galleryRegistryDbName(), 1);
        req.onupgradeneeded = () => { const db = req.result; if (!db.objectStoreNames.contains(STORE))
            db.createObjectStore(STORE); };
        req.onsuccess = () => { req.result.onversionchange = () => { req.result.close(); _dbPromise = null; }; resolve(req.result); };
        req.onerror = () => { _dbPromise = null; reject(req.error); };
        req.onblocked = () => reject(new Error("gallery-registry db upgrade blocked"));
    });
    return _dbPromise;
}
function _tx(mode, run) {
    return _openDB().then((db) => new Promise((resolve, reject) => {
        const tx = db.transaction(STORE, mode);
        let out;
        try {
            out = run(tx.objectStore(STORE));
        }
        catch (e) {
            reject(e);
            return;
        }
        tx.oncomplete = () => resolve(out ? out.result : undefined);
        tx.onerror = () => reject(tx.error);
        tx.onabort = () => reject(tx.error ?? new Error("gallery-registry db tx aborted"));
    }));
}
export function idbRegistryKV() {
    return {
        put: (e) => _tx("readwrite", (s) => { s.put(e, e.id); }),
        delete: (id) => _tx("readwrite", (s) => { s.delete(id); }),
        list: async () => (await _tx("readonly", (s) => s.getAll())) ?? [],
    };
}
/** 浏览器单例（懒开库：import 本身零 IDB 访问，node 测试 import 安全）。 */
export const galleryRegistry = createGalleryRegistry(idbRegistryKV());
