// mp3.ts —— 主线程这边：起一个 mp3 编码 worker，编完就关（重资源等有意图才加载：点导出才下这个 worker）。created 2026-10-07 by Claude Opus 5.5
// user「mp3不行吗，嫌弃胖子」：最初只有单声道 64 kbps（60 秒约 0.5 MB）。2026-10-08 导出面板（user「好，同意」）：标准 = 立体声 128 kbps（约 1 MB / 分钟，默认）/ 小文件 = 单声道 64 kbps。
import { _t } from "../i18n/index.ts";
import type { Mp3Reply, Mp3Request } from "./mp3-worker.ts";
import { startWorker, workersFetchSiteFiles } from "../threads.ts";
import { getBytes } from "../resources.ts";

export type Mp3Quality = "standard" | "small";
export const MP3_QUALITY: Record<Mp3Quality, { label: string; note: string; stereo: boolean; kbps: number }> = {
  standard: { label: _t("标准"), note: _t("立体声 192k，约 1.4 MB / 分钟"), stereo: true, kbps: 192 },   // 2026-10-17 user「标准192同意」（定稿 mp3 查案：ai-docs/20261017-final-mp3-quality.md）
  small: { label: _t("小文件"), note: _t("单声道 64k，约 0.5 MB / 分钟"), stereo: false, kbps: 64 },
};

/** 立体声（right 给了）或单声道。样本拷一份再转移给 worker，原样本（缓存里的）不动。 */
export function encodeMp3(left: Float32Array, right: Float32Array | null, sr: number, kbps = 64): Promise<Uint8Array<ArrayBuffer>> {
  // 备用版（data: 起的线程联不了网）：LAME 的胶水和 wasm 由这边经 resources.ts 读好交过去（2026-11-03 家族工单 A）
  const lame = workersFetchSiteFiles() ? Promise.resolve(undefined)
    : Promise.all([getBytes("vendor/lame/lame.mjs"), getBytes("vendor/lame/lame.wasm")]).then(([js, wasm]) => ({ js: js.slice().buffer as ArrayBuffer, wasm: wasm.slice().buffer as ArrayBuffer }));
  return lame.then((lib) => new Promise((ok, fail) => {
    const w = startWorker("mp3-worker");   // 起法归 threads.ts
    w.onmessage = (ev: MessageEvent<Mp3Reply>) => { w.terminate(); if (ev.data.ok) ok(ev.data.bytes); else fail(new Error(ev.data.message)); };
    w.onerror = (e) => { w.terminate(); fail(new Error(e.message || _t("mp3 编码 worker 出错"))); };
    const req: Mp3Request = { left: left.slice(), ...(right ? { right: right.slice() } : {}), sr, kbps, ...(lib ? { lame: lib } : {}) };
    w.postMessage(req, [req.left.buffer, ...(req.right ? [req.right.buffer] : []), ...(lib ? [lib.js, lib.wasm] : [])]);
  }));
}
