const _mem = new Map();
let _kv = { get: (k) => _mem.get(k) ?? null, set: (k, v) => { if (v == null)
        _mem.delete(k);
    else
        _mem.set(k, v); } };
export function configureDeviceKv(kv) { _kv = kv; }
export function deviceKvGet(key) { try {
    return _kv.get(key);
}
catch {
    return null;
} }
export function deviceKvSet(key, v) { try {
    _kv.set(key, v);
}
catch { /* 存不进（私密模式/配额）= 静默，读侧回退默认 */ } }
export function deviceKvGetJson(key, fallback) {
    const raw = deviceKvGet(key);
    if (raw == null)
        return fallback;
    try {
        return JSON.parse(raw);
    }
    catch {
        return fallback;
    }
}
export function deviceKvSetJson(key, v) { deviceKvSet(key, v === undefined ? null : JSON.stringify(v)); }
