// ⚠ 使用前必读 README.md + CONTEXT.md。app 不直接 import——经 createStore。
//
// freshness（深模块）—— 进入/事件时的"云端动没动 → clean 快进 / dirty surface"。单一职责 =
//   freshness gate（ADR-0016）：比 seenBase vs 云端 etag；clean 且动过 → 静默无损快进；
//   dirty 且动过 → 交 ui 选（绝不静默覆盖 dirty）。编排 local-head.seenBase/isDirty + safe-resolve.safePull。
//   open = 开 session 的 gate（probe 可跳到离线）；refresh = 事件驱动(focus/visibility/online)的纯干净快进。
import { reportStoreError } from "../base/error-handling.js"; // 全接但分级：静默 swallow 也 funnel（不改控制流）
const passBusy = (_l, fn) => fn();
export function createFreshness(cfg) {
    const { cloud, head, safeResolve, busy: _busy = passBusy, hints, lineageFromDurable = true } = cfg;
    // 0.18.0：云端核对没跑成时，干净 ∧ 有 durable etag → 以它为 base（JSDoc 见 FreshnessCfg.lineageFromDurable）。
    //   脏的一律不碰（脏副本的 parent 只能由 recordEdit / 云端确认过的 markSeen 给；从 durable 补 parent 在多标签页下会变成静默覆盖）。
    const adoptDurableBase = (name, localDirty) => {
        if (!lineageFromDurable)
            return;
        if (head.isDirtyAnywhere(name) || (localDirty ? localDirty() : false))
            return;
        const d = head.seenBase(name);
        if (d != null)
            head.markSeen(name, d);
    };
    // 0.17.0：刚列过的云端帧里这个文件的 etag === 本 tab 已见 base → 云端没动，和 fetchMeta 得到同样结论，省一趟。
    //   提示说别的（动了 / 没有）一律不采信（可能比我们自己刚推的还旧）。
    const hintedInSync = (name) => {
        const h = hints?.peek(name);
        const base = head.seenBase(name);
        return !!h && base != null && h.etag === base;
    };
    // safePull 失败原因 → 用户能懂的短语（喂 reportStoreError；技术 reason 原样兜底）。
    const pullFailText = (reason) => reason === "invalid-cloud-bytes" ? "云端内容没通过校验，可能是公共 Wi-Fi 登录页劫持或文件损坏"
        : reason === "cloud-vanished" ? "云端文件刚刚被移动或删除"
            : reason === "backup-failed" ? "本地留底失败，为保数据没有覆盖"
                : reason;
    async function open(name, opts = {}) {
        const { isOnline = () => true, probe, onNewer, adopt, localDirty, busy = passBusy, localBytes } = opts;
        if (!isOnline()) {
            adoptDurableBase(name, localDirty);
            return { source: "local", reason: "offline" };
        }
        if (hintedInSync(name)) {
            head.markSeen(name, head.seenBase(name));
            return { source: "local", reason: "in-sync" };
        } // 同下面 meta.etag===base 分支，只是证据来自刚列的帧
        return busy("cloud.checking", async () => {
            let meta;
            if (probe) {
                const raced = await Promise.race([
                    cloud.fetchMeta(name).then((m) => ({ k: "meta", m }), (e) => ({ k: "err", e })),
                    Promise.resolve(probe).then(() => ({ k: "skip" })),
                ]);
                if (raced.k === "skip") {
                    adoptDurableBase(name, localDirty);
                    return { source: "local", reason: "skipped" };
                }
                if (raced.k === "err") {
                    adoptDurableBase(name, localDirty);
                    return { source: "local", reason: "cloud-error" };
                }
                meta = raced.m;
            }
            else {
                try {
                    meta = await cloud.fetchMeta(name);
                }
                catch (e) {
                    reportStoreError(e, "log");
                    adoptDurableBase(name, localDirty);
                    return { source: "local", reason: "cloud-error" };
                }
            }
            if (!meta)
                return { source: "local", reason: "cloud-absent" };
            const base = head.seenBase(name);
            if (base != null && meta.etag === base) {
                // 云端 === 本 tab 已见 base（没动）→ in-sync。reload 后内存 _base 空（seenBase 回退共享 etag），
                //   此时 markSeen 重捕 _base（dirty 还顺带重捕 _parent，local-head.ts:82）→ 闭合「dirty 但 _base 空 →
                //   下次推走 no-base fail → 误报 CloudNameCollisionError」窗口。只在 meta.etag===base（云端没动）调=安全：
                //   云端动过会落到下面 dirty→surface 路径，绝不在这里前推 parent（防 B1 silent-overwrite）。
                head.markSeen(name, meta.etag);
                return { source: "local", reason: "in-sync" };
            }
            // !base（无 baseline：从未 synced 的血统 / 谱系丢失）∧ 云端有文件 → 按「云端有别的版本」处理，
            //   对齐 listing.classifySyncState 的 `moved = cloudMoved || !everSynced`（同一事实不许两种结论）。
            //   旧版把 !base 判 in-sync = 静默保留陈旧本地（缺陷 B，20260820-open-time-conflict-surface-handoff）。
            const dirty = head.isDirtyAnywhere(name) || (localDirty ? localDirty() : false); // 全局问题用 isDirtyAnywhere（2026-08-21：别 tab 的未推字节 per-tab 视角看不见）
            if (!dirty) { // clean → 静默快进（无 sheet；safePull 因 clean 跳备份——!base 例外，谱系未知必备份）
                const r = await safeResolve.safePull(name, { adopt });
                // 快进没承诺过什么 → 失败只 info（状态栏，不 banner；captive portal 下每次 open 都会走到这里）。
                if (!r.ok && r.reason !== "edited-during-pull")
                    reportStoreError(new Error(`「${name}」云端有新版本但暂时取不到（${pullFailText(r.reason)}），已打开本地版本`), "info"); // 途中保存导致的作罢不是故障：本地有了未推改动，之后推送自会撞冲突面
                return r.ok ? { source: "fast-forwarded", backupName: r.backupName } : { source: "local", reason: r.reason, error: r.error };
            }
            // 2.2.2：弹面之前先试回执丢失自愈——拉云端逐字节比，一样就认领（同 push 的 tryHeal）。慢网：probe（「跳过到离线」）先到 → 当 skipped（不弹面、谱系不动；
            //   迟到的比对若相等仍会 markSynced，那是关于字节的事实、无害）。拉失败 = 比不出，照旧交 ui。
            //   先用 meta 里的大小当闸（零网络）：大小不同 = 不可能一样 → 不拉、直接弹面（守住「面前不预拉整份云端」——QA 2026-08-20 / store-open-conflict 测试）；大小一样才拉来逐字节比。
            if (localBytes && safeResolve.tryHeal) {
                const mine = await localBytes().catch((e) => { reportStoreError(e, "log"); return null; });
                if (mine && (meta.size == null || meta.size === mine.byteLength)) {
                    const healing = (async () => { try {
                        return await safeResolve.tryHeal(name, mine);
                    }
                    catch (e) {
                        reportStoreError(e, "log");
                        return false;
                    } })();
                    const outcome = probe ? await Promise.race([healing.then((h) => ({ k: "heal", h })), Promise.resolve(probe).then(() => ({ k: "skip" }))]) : { k: "heal", h: await healing };
                    if (outcome.k === "skip")
                        return { source: "local", reason: "skipped" };
                    if (outcome.h)
                        return { source: "local", reason: "healed" };
                }
            }
            // dirty 分叉 → 交 ui（takeCloud=拉 / keepMine|cancel=留本地）
            const choice = onNewer ? await onNewer({ name, cloudEtag: meta.etag, baseEtag: base, cloudTime: meta.lastModified }) : "cancel";
            if (choice === "takeCloud") {
                // forceBackup：这里本来就是 dirty（必备份），加它不改变备份行为；它表达的是「用户明确选了换世界线」——
                //   下载途中又保存过时，safePull 据此把那一份再备份一次然后照用户的意思覆盖，而不是作罢（0.15.2）。
                const r = await safeResolve.safePull(name, { adopt, forceBackup: true });
                // 用户显式选了「用云端」却没成 → warning（banner）：绝不让用户以为打开的是云端版（反煤气灯）。
                if (!r.ok)
                    reportStoreError(new Error(`「${name}」未能取回云端版本（${pullFailText(r.reason)}），本次打开的仍是本地版本`), "warning");
                return r.ok ? { source: "pulled", backupName: r.backupName } : { source: "local", reason: r.reason, backupName: r.backupName, error: r.error };
            }
            return { source: "local", reason: "kept" };
        });
    }
    // 事件驱动干净快进：dirty → no-op（绝不在事件里弹 sheet；后续 push 的 412 会 surface 真分叉）。
    async function refresh(name, opts = {}) {
        const { isOnline = () => true, adopt, localDirty, onReplaceStart, probe, busy = passBusy, trustHints = true } = opts;
        if (!isOnline())
            return { status: "offline" };
        if (head.isDirtyAnywhere(name) || (localDirty && localDirty()))
            return { status: "dirty-skip" }; // anywhere：快进覆盖的是**共享**本地字节，别 tab 的未推编辑也要挡
        if (trustHints && hintedInSync(name)) {
            head.markSeen(name, head.seenBase(name));
            return { status: "in-sync" };
        } // 0.18.1：trustHints:false = 醒来 / 回前台这种时刻一定问云端
        return busy("cloud.checking", async () => {
            let meta;
            try {
                meta = await cloud.fetchMeta(name);
            }
            catch (e) {
                reportStoreError(e, "log");
                return { status: "cloud-error" };
            }
            if (!meta)
                return { status: "cloud-absent" };
            const base = head.seenBase(name);
            // !base ∧ 云端有 → 同 open：按 moved 处理（对齐 listing；clean-only 路径 → 直接快进采纳云端）。
            if (base != null && meta.etag === base) {
                // 0.16.2（2026-10-08，MoonSinger「写着写着过一会就跳一次冲突面」案）：in-sync 也要 markSeen 重捕 _base——和 open 的同一分支对称。
                //   reload 后内存 _base 空；宿主要是在登录**之前**就开了文档（MoonSinger / WXHW 的 boot 顺序：建 store → 本地恢复 → initAuth），
                //   open 的 gate 因云端不可达跳过、没重捕；登录后走的是这里（pullIfClean）——以前直接 return，_base 永远空 →
                //   本 tab 第一次编辑 recordEdit 捕到 parent=null → 推不带 If-Match → conflictBehavior:"fail" → 409 → 误报
                //   CloudNameCollisionError 冲突面（每次 reload 一次；人选「本地覆盖云端」markSynced 之后才好）。
                //   安全性同 open 那一行：云端 === 本 tab 已见 base（没动）才调；且进到这里之前 isDirtyAnywhere 已经挡过——只给干净 tab 重捕，
                //   绝不在云端动过时前推 parent（B1 silent-overwrite 守住）。
                head.markSeen(name, meta.etag);
                return { status: "in-sync" };
            }
            if (head.isDirtyAnywhere(name) || (localDirty && localDirty()))
                return { status: "dirty-skip" }; // anywhere：快进覆盖的是**共享**本地字节，别 tab 的未推编辑也要挡  // fetchMeta 期间用户动了笔 → 放弃
            if (onReplaceStart)
                onReplaceStart();
            // 逃生 race（2026-08-25）：probe 先到 → "escaped"（分叉 consent）。safePull 继续在后台跑完 = 原名
            //   缓存静默刷新（这里没传 adopt 时画布不碰；错误 funnel 到 log，不打扰已走人的用户）。
            const pulling = safeResolve.safePull(name, { adopt });
            if (probe) {
                const winner = await Promise.race([pulling.then((r) => ({ r })), Promise.resolve(probe).then(() => null)]);
                if (winner == null) {
                    pulling.catch((e) => reportStoreError(e, "log"));
                    return { status: "escaped" };
                }
                return winner.r.ok ? { status: "fast-forwarded" } : winner.r.reason === "edited-during-pull" ? { status: "dirty-skip" } : { status: "ff-failed", reason: winner.r.reason };
            }
            const r = await pulling;
            if (!r.ok && r.reason === "edited-during-pull")
                return { status: "dirty-skip" }; // 0.15.2：下载途中本地有了改动 → 这次快进作罢（同「本来就脏」）
            return r.ok ? { status: "fast-forwarded" } : { status: "ff-failed", reason: r.reason };
        });
    }
    return { open, refresh };
}
